head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vAxisType = "";
scwin.vHorizLimitCnt = 0;
scwin.vVertiLimitCnt = 2000;
window.onunload = function() {
    opener.fn_getBeforeRadioBtn("ALL");
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P5.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    $c.cm.PanelToGroupBox(panel_1);

    // 데이터셋 초기화
    scwin.initDs();

    // 기본값 세팅
    scwin.setDefaultVal();

    // 년도콤보세팅
    await scwin.getYear(dts_Year);

    // chb_COL_YEAR 체크박스 제어
    await scwin.ctrlChbCOLYEAR();
};

