 * @param {*} bCheck bCheck
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_oncheckclick = function(col, colid, bCheck) {
    try {
        let nSelectCnt = 0;
        for (let nRow = 1; nRow <= dts_List.getRowCount(); nRow++) {
            if (dts_List.getCellData(nRow, "CHK") === "T") {
                nSelectCnt++;
            }
        }
        txb_TotCnt.setValue("선택건수 " + nSelectCnt + "건");
