/**
 * @method
 * @name getYear
 * @description 년도콤보 세팅. 년도구하기
 * @param {*} pDataSet pDataSet
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getYear = async function(pDataSet) {
    const sbmOptions = {
        id : "sbm_pDataSet",
        action : "/listingCommon.do",
        ref : "",
        target : "pDataSet=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    if (pDataSet.id === "dts_Year") {
        scwin.setYearVal();
    }
};

/**
 * @method
 * @name search
 * @description 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    // 데이터셋 초기화
    scwin.clearDs();

    // 조회조건 필수 체크.
    if (!await scwin.chkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

