/**
 * @method
 * @name chbCOLYEAROnClick
 * @description 체크박스 온클릭
 * @returns {void}
 * @hidden N
 */
scwin.chbCOLYEAROnClick = function() {
    dts_SelectCom.removeAll();
    txb_TotCnt2.setValue("총 " + dts_SelectCom.getRowCount() + "건");
    if (chb_COL_YEAR.getValue() === "Y") {
        cmb_COL_YEAR.setDisabled(false);
        cmb_COL_YEAR.setSelectedIndex(0);
    } else {
        cmb_COL_YEAR.setDisabled(true);
        cmb_COL_YEAR.setSelectedIndex(-1);
    }
};

/**
 * @method
 * @name setDefaultVal
 * @description 화면의 기본값 세팅
 * @returns {void}
 * @hidden N
 */
scwin.setDefaultVal = function() {
    txb_FISCAL_TYP_NM.setValue($c.stf.getObjectText(opener.cmb_FISCAL_TYP));
    txb_IND_PTTN.setValue(opener.cmb_IND_PTTN.getValue());
    txb_FISCAL_TYP.setValue(opener.cmb_FISCAL_TYP.getValue());
    txb_INDVDL_CONN_TP.setValue(opener.cmb_INDVDL_CONN_TP.getValue());
    txb_ACNTG_BAS_TYP.setValue(opener.cmb_ACNTG_BAS_TYP.getValue());
    edt_DT.setValue($c.ut.cGetToday2());
    scwin.vAxisType = opener.scwin.vAxisType;
    scwin.vHorizLimitCnt = opener.scwin.vHorizLimitCnt;
    if (scwin.vAxisType === "2") {
        txb_limitText.setValue("* 선택 가능한 기업의 갯수는 최대 10개 입니다.");
    }
};

/**
 * @method
 * @name setYearVal
 * @description 년도 조회 후 년도 콤보 세팅 OPENER에 기준으로 년도가 세팅된경우 해당 년도를 기본값으로 세팅한다.
 * @returns {void}
 * @hidden N
 */
scwin.setYearVal = function() {
    // AXIS_TYP  1 기준, 2 가로축, 3 세로축
    let nTmpIdx1 = opener.dts_Fz531.NameValueRow("AXIS_TYP", "1");
    if (nTmpIdx1 >= 1) {
        const ITEM_TYP = opener.dts_Fz531.getCellData(nTmpIdx1, "ITEM_TYP"); // ITEM_TYP  0 년도, 1 계정, 3 회사
        if (ITEM_TYP === "0") {
            cmb_FISCAL_YYYY.setValue(opener.dts_Fz531.getCellData(nTmpIdx1, "ITEM_CD"));
        }
    }
};

