/**
 * @method
 * @name chkValid
 * @description 조회조건 유효성 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkValid = async function() {
    for (let nRow = 1; nRow <= dts_ConditionList.getRowCount(); nRow++) {
        if (dts_ConditionList.getCellData(nRow, "ACCNT_CD") === "") {
            await $c.win.alert("재무항목을 선택하세요.");
            grd_Condition.focus();
            return false;
        }
        if (dts_ConditionList.getCellData(nRow, "OPERATION") === "") {
            await $c.win.alert("연산자를 선택하세요.");
            grd_Condition.focus();
            return false;
        }
        if (dts_ConditionList.getCellData(nRow, "PRC") === "") {
            await $c.win.alert("금액을 입력하세요.");
            grd_Condition.focus();
            return false;
        }
        if (dts_ConditionList.getCellData(nRow, "ANDOR") === "") {
            await $c.win.alert("관계연산자를 선택하세요.");
            grd_Condition.focus();
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name getSqlCondition
 * @description 재무관련 조건을 생성한다.
 * @returns {void}
 * @hidden N
 */
scwin.getSqlCondition = function() {
    if (dts_ConditionList.getRowCount() < 1) {
        return "";
    }
    let sTmpCol = "";
    let sTmp1 = "";
    let sTmp2 = "";
    let sTmp3 = "";
    for (let nRow = 1; nRow <= dts_ConditionList.getRowCount(); nRow++) {
        sTmpCol += ", SUM(DECODE(ACCNT_PTTN||ACCNT_CD,'" + dts_ConditionList.getCellData(nRow, "ACCNT_CD") + "', ACCNT_VAL)) \n";
        sTmp1 += "SUM(DECODE(ACCNT_PTTN||ACCNT_CD,'" + dts_ConditionList.getCellData(nRow, "ACCNT_CD") + "', ACCNT_VAL))";
        sTmp1 += (dts_ConditionList.getCellData(nRow, "OPERATION") === "1" ? " <= " : " >= ") + dts_ConditionList.getCellData(nRow, "PRC") + " ";
        sTmp1 += (nRow === dts_ConditionList.getRowCount() ? "" : dts_ConditionList.getCellData(nRow, "ANDOR")) + " \n";
        sTmp2 += ",'" + dts_ConditionList.getCellData(nRow, "ACCNT_CD").substring(0, 1) + "'";
        sTmp3 += ",'" + dts_ConditionList.getCellData(nRow, "ACCNT_CD").substring(1) + "'";
    }

    /**
     * 조건에따라 테이블이름 구하기.
     * TB_FN_FE110    개별 KGGAP
     * TB_FN_FE120    개별 IFRS
     * TB_FN_FE310    연결 KGGAP
     * TB_FN_FE320    연결 IFRS
     */
    const sTableNm = opener.fn_GetTableName();
    let sCond = "";
    if (dts_ConditionList.getRowCount() >= 1) {
        sCond = "AND EXISTS (SELECT KIS_CD \n" + sTmpCol + "              FROM " + sTableNm + " A \n" + "             WHERE KIS_CD = C.KIS_CD \n" + "               AND FISCAL_TYP = '" + txb_FISCAL_TYP.getValue() + "' \n" + "               AND FISCAL_YYYY = '" + cmb_FISCAL_YYYY.getValue() + "' \n" + "               AND FISCAL_MM = (SELECT MAX(FISCAL_MM) FROM " + sTableNm + " \n" + "                                 WHERE FISCAL_TYP='" + txb_FISCAL_TYP.getValue() + "' \n" + "                                   AND FISCAL_YYYY = '" + cmb_FISCAL_YYYY.getValue() + "' \n" + "                                   AND KIS_CD = A.KIS_CD) + \n" + "               AND ACCNT_PTTN IN (" + sTmp2.substring(1) + ") \n" + "               AND ACCNT_CD IN (" + sTmp3.substring(1) + ") \n" + "             GROUP BY KIS_CD \n" + "            HAVING (" + sTmp1 + "))";
    }
    return sCond;
};

/**
 * @method
 * @name setParam
 * @description 선택된 값을 오프너에 전달한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParam = async function() {
    if (dts_SelectCom.getRowCount() < 1) {
        return;
    }
    let arrPar = new Array();
    for (let nRow = 1; nRow <= dts_SelectCom.getRowCount(); nRow++) {
        const sItemCd = dts_SelectCom.getCellData(nRow, "KIS_CD");
        const sItemNM = dts_SelectCom.getCellData(nRow, "CO_SNM");
        const sItemTyp = "3"; // 0:년도, 1:계정, 3:회사
        const sAxisTyp = scwin.vAxisType; // AXIS_TYP  1:기준, 2: 가로, 3:세로
        const sColYear = dts_SelectCom.getCellData(nRow, "COL_YEAR");
        if (sItemCd !== "") {
            arrPar[nRow - 1] = {
                ITEM_CD: sItemCd,
                ITEM_NM: sItemNM,
                ITEM_TYP: sItemTyp,
                AXIS_TYP: sAxisTyp,
                COL_YEAR: sColYear
            };
        }
    }
    $c.frame.path("../").fn_SetAxisInfo(arrPar);
    await $c.win.closePopup();
};

