/**
 * @method
 * @name rmSelected
 * @description 선택제거
 * @returns {void}
 * @hidden N
 */
scwin.rmSelected = function() {
    dts_SelectCom.setBroadcast(false);
    while (true) {
        let nRow = $c.cp.getNameValueRow(dts_SelectCom, "CHK", "T");
        if (nRow < 1) {
            break;
        }
        dts_SelectCom.removeRow(nRow);
    }
    dts_SelectCom.setBroadcast(true, true);
    txb_TotCnt2.setValue("총 " + dts_SelectCom.getRowCount() + "건");
};

/**
 * @method
 * @name selected
 * @description 선택
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.selected = async function() {
    // dts_SelectCom.ClearData();

    MxGrid_1.ReDraw = false;
    grd_List.ReDraw = false;

    // 이미 선택된것 갯수
    let nSelectCnt = dts_SelectCom.getRowCount();

    // 가로 세팅이면 갯수 체크 :  2 가로, 3 세로
    if (scwin.vAxisType === "2") {
        for (let nRow = 1; nRow <= dts_List.getRowCount(); nRow++) {
            if (dts_List.getCellData(nRow, "CHK") === "T") {
                nSelectCnt++;
            }

            // 갯수체크
            if (nSelectCnt > scwin.vHorizLimitCnt) {
                await $c.win.alert("선택된 가로항목이 10개를 초과합니다.");
                return;
            }
        }
    }

    // 이미 선택된것 갯수 리셋
    nSelectCnt = dts_SelectCom.getRowCount();

    // 중복된것을 제거하자.
    // 데이터조회기준년도 체크되어있으면 KIS_CD + COL_YEAR 로 체크/
    // 언체크이면 KIS_CD 로 체크.
    const chkYear = chb_COL_YEAR.getValue();
    const valYear = cmb_COL_YEAR.getValue();
    dts_List.setBroadcast(false);
    dts_SelectCom.setBroadcast(false);
    for (let nRow = 1; nRow <= dts_List.getRowCount(); nRow++) {
        if (dts_List.getCellData(nRow, "CHK") === "T") {
            // 중복 체크.--------------------------------------------------------------------------------------------------------------------------------------------------------
            if (chkYear === "Y") {
                let bDup = false;
                let sTmp1 = dts_List.getCellData(nRow, "KIS_CD") + valYear;
                for (let nIdx = 1; nIdx <= dts_SelectCom.getRowCount(); nIdx++) {
                    let sTmp2 = dts_SelectCom.getCellData(nIdx, "KIS_CD") + dts_SelectCom.getCellData(nIdx, "COL_YEAR");
                    if (sTmp1 === sTmp2) {
                        bDup = true;
                        continue;
                    }
                }
                if (bDup) {
                    dts_List.setCellData(nRow, "CHK", "F");
                    continue;
                }
            } else {
                let nTmpIdx1 = $c.cp.getNameValueRow(dts_SelectCom, "KIS_CD", dts_List.getCellData(nRow, "KIS_CD"));
                if (nTmpIdx1 >= 1) {
                    dts_List.setCellData(nRow, "CHK", "F");
                    continue;
                }
            }
            // 중복 체크.--------------------------------------------------------------------------------------------------------------------------------------------------------

            dts_SelectCom.insertRow();
            let nIdx = dts_SelectCom.getRowPosition();
            // dts_SelectCom.NameString(nIdx, "CHK")      = "F";

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            //
            // ********************************************************************

            /*ORG SRC: dts_SelectCom.NameString(nIdx, "CO_SNM") = chkYear == "Y" ? valYear + " " + dts_List.NameString(nRow, "CO_SNM") : dts_List.NameString(nRow, "CO_SNM");*/
            X = chkYear === "Y" ? valYear + " " + dts_List.getCellData(nRow, "CO_SNM") : dts_List.getCellData(nRow, "CO_SNM");
            dts_SelectCom.setCellData(nIdx, "KIS_CD", dts_List.getCellData(nRow, "KIS_CD")); /*ORG SRC: dts_SelectCom.NameString(nIdx, "COL_YEAR") = chkYear == "Y" ? valYear : "0000";*/ X = chkYear === "Y" ? valYear : "0000";
            dts_List.setCellData(nRow, "CHK", "F");
            nSelectCnt++;
            if (nSelectCnt >= scwin.vVertiLimitCnt) {
                await $c.win.alert("선택 가능한 기업의 갯수는 최대 2000개 입니다.");
                break;
            }
        }
    }
    dts_List.setBroadcast(true, true);
    dts_SelectCom.setBroadcast(true, true);
    MxGrid_1.ReDraw = true;
    grd_List.ReDraw = true;
    txb_TotCnt2.setValue("총 " + dts_SelectCom.getRowCount() + "건");
};

/**
 * @method
 * @name ctrlChbCOLYEAR
 * @description 가로항목인 경우만 선택 가능. 잘못봤다 세로도 선택가능.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ctrlChbCOLYEAR = async function() {
    // 기준이 선택되어있다면 비활성.
    // 어딘가에서 년도가 선택되었다면 비활성.
    // 어딘가에서 이미 체크가 되었다면 비활성. => COL_YEAR 이 0000이 아닌게 존재한다.
    const tmpDs = opener.dts_Fz531;
    // 어딘가에서 이미 체크가 되었다면 비활성. => COL_YEAR 이 0000이 아닌게 존재한다.
    let bChecked = false;
    for (let nRow = 1; nRow <= tmpDs.getRowCount(); nRow++) {
        if (tmpDs.getCellData(nRow, "COL_YEAR") !== "0000") {
            bChecked = true;
            break;
        }
    }

    // 기준이 선택되어있다면 비활성.
    // 어딘가에서 년도가 선택되었다면 비활성.
    let nTmpIdx1 = tmpDs.NameValueRow("AXIS_TYP", "1");
    const nTmpIdx2 = tmpDs.NameValueRow("ITEM_TYP", "0"); // ITEM_TYP  0 년도, 1 계정, 3 회사
    if (nTmpIdx1 < 1 && nTmpIdx2 < 1 && !bChecked) {
        // 년도콤보세팅
        await scwin.getYear(dts_Year1);
        chb_COL_YEAR.setDisabled("");
        chb_COL_YEAR.setValue(1);
        scwin.chbCOLYEAROnClick(true);
    }
};

